/// Run the network on an int8 input in the `INPUT` grid.
pub fn forward(input: &Input) -> Output {
    let mut b0 = [[[0i8; 5]; 24]; 8];
    let mut b1 = [[[0i8; 5]; 12]; 4];
    let mut b2 = [[[0i8; 5]; 12]; 4];
    let mut b3 = [[[0i8; 5]; 12]; 4];
    let mut b4 = [[[0i8; 5]; 6]; 2];
    let mut b5 = [[[0i8; 5]; 1]; 1];
    CONV0.forward(input, &mut b0);
    MAXPOOL1.forward(&b0, &mut b1);
    DW2.forward(&b1, &mut b2);
    for x in b1.as_flattened_mut().as_flattened_mut() {
        *x = apply_lut(*x, &TANH3_LUT);
    }
    PW4.forward(&b2, &mut b3);
    ADD5.forward(&b1, &b3, &mut b2);
    for x in b2.as_flattened_mut().as_flattened_mut() {
        *x = apply_lut(*x, &SIGMOID6_LUT);
    }
    AVGPOOL7.forward(&b2, &mut b4);
    AVGPOOL8.forward(&b4, &mut b5);
    let v9 = FC9.forward(
        b5.as_flattened()
            .as_flattened()
            .first_chunk::<5>()
            .expect("5 values"),
    );
    SOFTMAX10.forward(&v9)
}
